"任何房间：出征带回的物资 +{0}%。契合「运势」：物资再 +{1}%，每场战斗初始积分倍率 +{2}。": "Libovolná místnost: zásoby z výprav +{0}%. Hodí se k „Štěstí“: zásoby ještě +{1}%, počáteční násobič bodů v každé bitvě +{2}.",
"任何房间：出征视野 +{0}，初始积分倍率 +{1}。契合「运势 / 特殊」：出征地图一开始就全亮，积分倍率再 +{2}。": "Libovolná místnost: dohled na výpravě +{0}, počáteční násobič bodů +{1}. Hodí se k „Štěstí / Speciální“: mapa výpravy odkrytá od začátku, násobič bodů ještě +{2}.",
"任何房间：出征部队攻击 +{0}%。契合「训练」：领袖出征得到的经验 +{1}%。": "Libovolná místnost: útok jednotek na výpravě +{0}%. Hodí se k „Výcvik“: XP vůdce z výprav +{1}%.",
"任何房间：出征部队生命 +{0}%。契合「医疗」：医院回复 +{1}%，领袖每天再回 {2}%。": "Libovolná místnost: zdraví jednotek na výpravě +{0}%. Hodí se k „Zdravotnictví“: léčení v nemocnici +{1}%, vůdce denně obnoví navíc {2}%.",
"任何房间：图纸掉率 +{0}%。契合「科幻」：基地每天 +{1} 灵魂碎片。": "Libovolná místnost: šance na plány +{0}%. Hodí se k „Sci-fi“: základna: Úlomky duší +{1} denně.",
"任何房间：图纸掉率 +{0}%。契合「锻造」：打造时 {1}% 概率多得一件。": "Libovolná místnost: šance na plány +{0}%. Hodí se k „Kovářství“: {1}% šance na relikvii navíc při kování.",
"任何房间：基地每天 +{0} 灵魂碎片。契合「魔法」：基地每天再 +{1} 灵魂碎片。": "Libovolná místnost: základna: Úlomky duší +{0} denně. Hodí se k „Magie“: navíc +{1} denně.",
"任何房间：基地每天 +{0} 物资。契合「后勤」：这个房间自己的效果 ×{1}。": "Libovolná místnost: základna: Zásoby +{0} denně. Hodí se k „Logistika“: vlastní účinek této místnosti ×{1}.",
