"任何房间：宝物打造费用 -{0}%。契合「锻造 / 武器」：锻造：{1}% 概率品质 +{2}；武器：伤害 +{3}%。": "Libovolná místnost: cena kování relikvií -{0}%. Hodí se k „Kovářství / Zbraň“: kovářství: {1}% šance na kvalitu +{2}; zbraně: poškození +{3}%.",
"任何房间：建造时间减半，建成返还 {0}% 物资。契合「奇观」：返还提高到 {1}%。": "Libovolná místnost: doba stavby poloviční, po dokončení vrácení {0}% zásob. Hodí se k „Div“: vrácení stoupne na {1}%.",
