"任何房间：挖掘费用 -{0}%。契合「特殊」：所有建造少花 {1} 天。": "Libovolná místnost: cena kopání -{0}%. Hodí se k „Speciální“: každá stavba je o {1} d. kratší.",
"任何房间：每场战斗初始积分倍率 +{0}。契合「锻造」：打造的宝物品质必定 +{1}。": "Libovolná místnost: počáteční násobič bodů v každé bitvě +{0}. Hodí se k „Kovářství“: ukované relikvie mají vždy kvalitu +{1}.",
"任何房间：领袖技能冷却少 {0} 个节点。契合「运势」：出征开局多带 {1} 个支援道具（至少转出「史诗」效果）。": "Libovolná místnost: obnovení schopnosti vůdce kratší o {0} et. Hodí se k „Štěstí“: na začátku výpravy podpůrné předměty navíc: {1} (efekt nejméně „Epický“).",
"任何房间：领袖攻击 +{0}%。契合「武器」：伤害 +{1}%，每次攻击放出连锁闪电（跳 {2} 个敌人）。": "Libovolná místnost: útok vůdce +{0}%. Hodí se k „Zbraň“: poškození +{1}%, každý útok vypustí řetězový blesk (cíle: {2}).",
"任何房间：领袖每天回复 {0}% 生命（不需要医院）。契合「医疗 / 水域」：医院回复 +{1}%；水域武器射程 +{2}。": "Libovolná místnost: vůdce obnoví {0}% zdraví denně (bez nemocnice). Hodí se k „Zdravotnictví / Voda“: léčení v nemocnici +{1}%; dostřel vodních zbraní +{2}.",
