"前面是": "Před tebou",
"前面是「墓园」：雾最浓的地方是镇外的墓园，新坟一夜比一夜多。": "Před tebou je „Hřbitov“: mlha je nejhustší na hřbitově za městem a nových hrobů každou noc přibývá.",
"前面是「总装车间」：工厂最后造出来的东西，把工厂里的人都装了进去。": "Před tebou je „Montážní hala“: poslední věc, kterou továrna vyrobila, do sebe vměstnala všechny její lidi.",
"前面是「手术室」：院长说手术很成功，病人只是还没醒。": "Před tebou je „Operační sál“: ředitel říká, že operace se povedla — pacient se jen ještě neprobudil.",
"前面是「海底」：港口下面还有一座城，城门是一张嘴。": "Před tebou je „Mořské dno“: pod přístavem je ještě jedno město a jeho brána je chřtán.",
"前面是「知识古树」：古树记得森林里发生过的每一件事，它不想再记住别的了。": "Před tebou je „Strom poznání“: starý strom si pamatuje vše, co se v lese kdy stalo. Nic dalšího si už pamatovat nechce.",
"前面是「精灵女王」：女王在月池边等了三百年。她说，你就是她等的那个人。": "Před tebou je „Elfí královna“: královna čekala u měsíčního jezírka tři sta let. Říká, že čekala právě na tebe.",
"前面是「马戏大棚」：大棚里的笑声从来没停过，只是再也没有观众。": "Před tebou je „Cirkusový stan“: smích ve stanu nikdy neutichl — jen už tam nejsou diváci.",
